class Solution {
public:
    vector<int> corpFlightBookings(vector<vector<int>>& bookings, int n) {
        vector<int> res(n, 0);
        for (const auto& b : bookings) {
            res[b[0] - 1] += b[2];
            if (b[1] < n) res[b[1]] -= b[2];
        }
        for (int i = 1; i < n; ++i) {
            res[i] += res[i - 1];
        }
        return res;
    }
};

class Solution {
    public int[] corpFlightBookings(int[][] bookings, int n) {
        int[] res = new int[n];
        for (int[] b : bookings) {
            res[b[0] - 1] += b[2];
            if (b[1] < n) res[b[1]] -= b[2];
        }
        for (int i = 1; i < n; i++) {
            res[i] += res[i - 1];
        }
        return res;
    }
}

var corpFlightBookings = function(bookings, n) {
    const res = new Array(n).fill(0);
    for (const [first, last, seats] of bookings) {
        res[first - 1] += seats;
        if (last < n) res[last] -= seats;
    }
    for (let i = 1; i < n; i++) {
        res[i] += res[i - 1];
    }
    return res;
};
